UPDATE public.community_links SET link_group = CASE WHEN lower(label) IN ('whatsapp admin','grup whatsapp') THEN 'Chat Admin & Komunitas' WHEN lower(label) IN ('upgrade private server','testimoni') THEN 'Dukung & Kepercayaan' ELSE 'Sosial & Roblox' END, description = CASE lower(label) WHEN 'whatsapp admin' THEN 'Tanya produk dan pemesanan langsung' WHEN 'grup whatsapp' THEN 'Gabung untuk info, promo, dan komunitas' WHEN 'upgrade private server' THEN 'Bantu dukung private server melalui Saweria' WHEN 'testimoni' THEN 'Lihat pengalaman pembeli lain' WHEN 'tiktok' THEN 'Ikuti @theblackprince_8' ELSE description END WHERE lower(label) IN ('whatsapp admin','grup whatsapp','upgrade private server','testimoni','tiktok');